const PokeballIcon_svg = `<img src="data:image/png;base64," style="padding: 0 !important; margin: 0 !important; width: 24px !important; height: 24px !important; border-radius: 50% !important; object-fit: cover !important; background-color: transparent !important; transform: scale(1.15) !important; vertical-align: middle !important; display: block !important;">`;

function initPkg_ExIcon() {
	initPkg_ExIcon_insertDom();
	initPkg_ExIcon_Func();
	if (typeof Update_refreshTip === "function") {
		Update_refreshTip();
	}
}
function initPkg_ExIcon_insertDom() {
	let a = document.createElement("div");
	a.className = "ex-icon";
	a.innerHTML = `<a title="DouyuX-斗鱼直播间增强(驴酱版) ver.${curVersion}">${PokeballIcon_svg}<i id="ex-icon__tip" class="ex-panel__tip"></i></a>`;
	let b = document.querySelector(".PlayerToolbar-ContentCell .PlayerToolbar-Wealth")
		|| document.querySelector(".ToolbarGiftArea-container")
		|| document.querySelector(".PlayerToolbar")
		|| document.querySelector(".BackpackButton")?.parentNode
		|| document.body;
		if (b) {
			b.appendChild(a);
		}
}
function initPkg_ExIcon_Func() {
	let icon = document.getElementsByClassName("ex-icon")[0];
	if (icon) {
		// 点击精灵球：
		//   ① 有三级面板展开时 = 「全部收敛」—— 收起所有三级面板，并把二级胶囊菜单一并折起
		//      （与二级菜单自己的折叠语义一致；否则面板还开着却把菜单折掉，用户会以为丢东西）；
		//   ② 没有三级面板展开时，保持原来的展开/折叠切换。
		icon.addEventListener("click", (e) => {
			e.stopPropagation();
			if (typeof isAnyThirdLevelPanelOpen === "function" && isAnyThirdLevelPanelOpen()) {
				if (typeof ExPanel_closeAllThirdLevel === "function") {
					ExPanel_closeAllThirdLevel();
				}
				if (typeof hideExPanel === "function") {
					hideExPanel();
				}
				return;
			}
			if (typeof toggleExPanel === "function") {
				toggleExPanel();
			} else if (typeof showExPanel === "function") {
				showExPanel();
			}
		});
	}
}

// 任务栏精灵球右上角更新提示橙色小标点
function ExIcon_showTip(a) {
	let d = document.getElementById("ex-icon__tip");
	if (!d) return;
	if (a === true) {
		d.style.display = "block";
	} else {
		d.style.display = "none";
	}
}
